'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { createClient } from '@/lib/supabase'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Loader2, Search, Users } from 'lucide-react'

export default function TeamsPage() {
    const [teams, setTeams] = useState<any[]>([])
    const [loading, setLoading] = useState(true)
    const [search, setSearch] = useState('')
    const supabase = createClient()

    useEffect(() => {
        async function fetchTeams() {
            const { data } = await supabase
                .from('pit_scouting')
                .select('team_number, event_key')
                .order('team_number')
            
            if (data) {
                const uniqueTeams = [...new Map(data.map(t => [t.team_number, t])).values()]
                setTeams(uniqueTeams)
            }
            setLoading(false)
        }
        fetchTeams()
    }, [supabase])

    const filteredTeams = teams.filter(t => 
        t.team_number.toString().includes(search)
    )

    if (loading) return (
        <div className="flex flex-col items-center justify-center min-h-screen">
            <Loader2 className="h-12 w-12 animate-spin text-primary opacity-20" />
            <div className="text-muted-foreground font-medium animate-pulse mt-4">Loading Teams...</div>
        </div>
    )

    return (
        <div className="container py-8 max-w-4xl mx-auto space-y-8">
            <div className="flex items-center gap-4">
                <Link href="/">
                    <Button variant="ghost" className="rounded-full h-12 w-12 p-0">
                        <Users className="h-6 w-6" />
                    </Button>
                </Link>
                <div>
                    <h1 className="text-4xl font-black tracking-tighter">Teams</h1>
                    <p className="text-muted-foreground font-medium">All teams in database</p>
                </div>
            </div>

            <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
                <Input
                    placeholder="Search team number..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    className="h-14 pl-12 rounded-2xl text-lg"
                />
            </div>

            {filteredTeams.length > 0 ? (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                    {filteredTeams.map((team) => (
                        <Link key={team.team_number} href={`/teams/${team.team_number}`}>
                            <Card className="hover:border-primary hover:shadow-lg transition-all cursor-pointer">
                                <CardHeader className="pb-2">
                                    <CardTitle className="text-2xl font-black">#{team.team_number}</CardTitle>
                                </CardHeader>
                                <CardContent>
                                    <Badge variant="outline" className="font-mono">{team.event_key}</Badge>
                                </CardContent>
                            </Card>
                        </Link>
                    ))}
                </div>
            ) : (
                <div className="text-center py-12 text-muted-foreground">
                    {search ? 'No teams found matching your search.' : 'No teams in database yet.'}
                </div>
            )}
        </div>
    )
}
